/* Johnber Shorts Studio — local, dependency-free editing client. */
'use strict';
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone = v => JSON.parse(JSON.stringify(v));
const icons = {
  projects:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="M3 9h18M8 9v11"/>',
  template:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="M3 9h18M14 9v12"/>',
  export:'<path d="M12 3v12m-4-4 4 4 4-4M5 15v5h14v-5"/>',
  settings:'<path d="m9 3 6 0 1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z"/><circle cx="12" cy="12" r="3"/>',
  plus:'<path d="M12 5v14M5 12h14"/>', upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',
  play:'<path d="m8 4 12 8-12 8z"/>', pause:'<path d="M8 4v16M16 4v16"/>',
  close:'<path d="m6 6 12 12M6 18 18 6"/>', arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',
  back:'<path d="M19 12H5m5-5-5 5 5 5"/>', search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',
  video:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="m10 8 6 4-6 4z"/>',
  text:'<path d="M4 5h16M12 5v15M8 20h8"/>', undo:'<path d="M9 5 4 10l5 5M4 10h10a5 5 0 0 1 0 10"/>',
  redo:'<path d="m15 5 5 5-5 5M20 10H10a5 5 0 0 0 0 10"/>', check:'<path d="m4 12 5 5L20 6"/>',
  save:'<path d="M4 3h14l3 3v15H3V3zM7 3v6h10V3M7 21v-8h10v8"/>',
  grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
  list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h1M3 12h1M3 18h1"/>',
  spark:'<path d="m12 3 3 6 6 3-6 3-3 6-3-6-6-3 6-3zM20 2v4M18 4h4"/>',
  copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',
  trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',
  help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 4M12 16v1"/>',
  folder:'<path d="M3 7V4h7l3 3h8v13H3z"/>',scissors:'<circle cx="6" cy="6" r="3"/><circle cx="6" cy="18" r="3"/><path d="m8 8 13 13M8 16 21 3"/>'
};
const icon = (name, size=16) => `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name] || icons.video}</svg>`;
const state = {page:'projects', projects:[], project:null, health:null, templates:[], jobs:[], clipId:null, element:'title', scope:'clip', cueId:null, inspector:'style', time:0, safe:true, cueSearch:'', projectSearch:'', list:false, dirty:false, saving:false, undo:[], redo:[], candidates:[], ranges:[], selectedClips:new Set(), previewUrl:null, frameSeq:0};
let saveTimer, frameTimer, pendingSave = Promise.resolve(), lastEditAt=0, pollTimer;
const names = {render:'MP4 내보내기',preview:'확정 미리보기',transcribe:'자동 전사',recommend:'구간 추천',silence:'무음 감지'};
const states = {queued:'대기 중',running:'처리 중',succeeded:'완료',failed:'실패',cancelled:'취소됨',interrupted:'중단됨'};
const activeJob = j => ['queued','running'].includes(j.state);
function time(v, decimal=false) { v=Math.max(0,Number(v)||0); const h=Math.floor(v/3600),m=Math.floor(v%3600/60),s=Math.floor(v%60); return `${h ? String(h).padStart(2,'0')+':' : ''}${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}${decimal ? '.'+String(Math.round((v%1)*100)).padStart(2,'0') : ''}`; }
function bytes(v) { return v>=1e9?(v/1e9).toFixed(1)+' GB':v>=1e6?(v/1e6).toFixed(1)+' MB':Math.round(v/1024)+' KB'; }
function toast(message, error=false) { const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('#toasts').append(el);setTimeout(()=>el.remove(),error?10000:4500); }
async function api(url, options={}) {
  const opts={...options}; if(opts.body && !(opts.body instanceof FormData)){opts.headers={...opts.headers,'Content-Type':'application/json'};opts.body=JSON.stringify(opts.body);}
  const r=await fetch(url,opts); if(!r.ok){let body;try{body=await r.json();}catch{body={detail:`서버 응답 오류 (${r.status})`};}const detail=body.detail ?? body.error ?? '요청을 처리하지 못했습니다.';throw new Error(typeof detail==='string'?detail:JSON.stringify(detail));}return r.status===204?null:r.json();
}
function clip() {return state.project?.clips?.find(c=>c.id===state.clipId) || state.project?.clips?.[0];}
function selectedCue(){return state.project?.cues.find(q=>q.id===state.cueId)||state.project?.cues.find(q=>q.end>clip()?.start&&q.start<clip()?.end);}
function styleTarget(key=state.element){const q=selectedCue();if(state.scope==='cue'&&q&&['subtitle','highlight'].includes(key)){const prop=key==='subtitle'?'style':'highlight_style';q[prop]??={};return q[prop];}return clip()?.style[key];}
function effectiveStyle(key=state.element){return {...(clip()?.style[key]||{}),...(state.scope==='cue'&&selectedCue()&&['subtitle','highlight'].includes(key)?selectedCue()[key==='subtitle'?'style':'highlight_style']||{}:{})};}
function retained(c=clip()) {
  if(!c)return [];const cuts=(c.cuts||[]).map(x=>({start:Math.max(c.start,x.start),end:Math.min(c.end,x.end)})).filter(x=>x.end>x.start).sort((a,b)=>a.start-b.start);let cursor=c.start;const out=[];for(const x of cuts){if(x.start>cursor)out.push({start:cursor,end:x.start});cursor=Math.max(cursor,x.end);}if(cursor<c.end)out.push({start:cursor,end:c.end});return out;
}
function duration(c=clip()){return retained(c).reduce((n,x)=>n+x.end-x.start,0)/(c?.speed||1);}
function sourceTime(t=state.time,c=clip()){let cursor=0;for(const x of retained(c)){const len=(x.end-x.start)/(c.speed||1);if(t<cursor+len)return x.start+(t-cursor)*(c.speed||1);cursor+=len;}return c?.end||0;}
function outputTime(t,c=clip()){let cursor=0;for(const x of retained(c)){if(t<=x.start)return cursor;if(t<x.end)return cursor+(t-x.start)/(c.speed||1);cursor+=(x.end-x.start)/(c.speed||1);}return cursor;}
function record(coalesce=false){if(!state.project)return;if(!coalesce||Date.now()-lastEditAt>1100){state.undo.push(clone({title:state.project.title,cues:state.project.cues,clips:state.project.clips}));if(state.undo.length>70)state.undo.shift();}lastEditAt=Date.now();state.redo=[];}
function changed(options={}){persistView();state.dirty=true;state.previewUrl=null;updateSaveStatus();clearTimeout(saveTimer);saveTimer=setTimeout(()=>save().catch(e=>toast(e.message,true)),700);if(options.frame!==false)scheduleFrame();updateUndo();}
function updateUndo(){const u=$('[data-action="undo"]'),r=$('[data-action="redo"]');if(u)u.disabled=!state.undo.length;if(r)r.disabled=!state.redo.length;}
function updateSaveStatus(){const el=$('#save-status');if(el)el.innerHTML=state.saving?'<span class="spinner" style="width:9px;height:9px"></span>저장 중':state.dirty?'저장하지 않은 변경사항':'모든 변경사항 저장됨';}
async function save(){clearTimeout(saveTimer);if(!state.project||!state.dirty)return pendingSave;const id=state.project.id;pendingSave=pendingSave.catch(()=>{}).then(async()=>{if(!state.dirty||state.project?.id!==id)return;state.saving=true;updateSaveStatus();const body=clone({title:state.project.title,cues:state.project.cues,clips:state.project.clips,revision:state.project.revision});state.dirty=false;try{const p=await api(`/api/projects/${id}`,{method:'PUT',body});if(state.project?.id===id){state.project.revision=p.revision;state.project.updated_at=p.updated_at;}}catch(e){state.dirty=true;throw e;}finally{state.saving=false;updateSaveStatus();}});return pendingSave;}
async function flush(){do{await save();await pendingSave;}while(state.dirty||state.saving);}
function persistView(){if(state.project&&state.page==='editor')localStorage.setItem('johnber-editor-view',JSON.stringify({projectId:state.project.id,clipId:state.clipId,time:state.time,element:state.element,inspector:state.inspector}));}
function nav(page){localStorage.setItem('johnber-page',page);if(state.page==='editor'&&state.dirty){flush().then(()=>{state.page=page;render();loadPage();}).catch(e=>toast(e.message,true));return;}state.page=page;render();loadPage();}
async function loadPage(){try{if(state.page==='projects')state.projects=await api('/api/projects');if(state.page==='templates')state.templates=await api('/api/templates');if(state.page==='exports')state.jobs=await api('/api/jobs');renderPage();}catch(e){toast(e.message,true);}}
function shell(){return `<div class="shell"><nav class="rail" aria-label="주 메뉴"><div class="brand-symbol" aria-label="존버나드">J.</div>${[['projects','projects','프로젝트'],['templates','template','템플릿'],['exports','export','완성 영상']].map(([p,i,n])=>`<button data-nav="${p}" class="${state.page===p||(p==='projects'&&state.page==='editor')?'active':''}" aria-label="${n}">${icon(i)}<span>${n}</span></button>`).join('')}<div class="rail-bottom"><button data-nav="settings" class="${state.page==='settings'?'active':''}">${icon('settings')}<span>설정</span></button><button data-action="help">${icon('help')}<span>도움말</span></button></div></nav><header class="app-header"><div class="wordmark">존버나드 쇼츠 스튜디오<span>JOHNBER SHORTS STUDIO</span></div><div class="row"><div class="local-status"><i class="dot"></i>로컬 스튜디오 <span>· 내 영상은 내 컴퓨터에</span></div><button class="sm ghost" data-action="upload">${icon('plus',14)} 새 프로젝트</button></div></header><main id="page"></main></div>`;}
function render(){const focus=document.activeElement?.id;$('#app').innerHTML=shell();renderPage();if(focus)$(`#${focus}`)?.focus();}
function renderPage(){const root=$('#page');if(!root)return;const focused=document.activeElement,focusSelector=root.contains(focused)?focused.id?'#'+focused.id:focused.dataset?.cueText?`[data-cue-text="${focused.dataset.cueText}"]`:focused.dataset?.style?`[data-style="${focused.dataset.style}"]`:null:null,selection=focusSelector&&typeof focused.selectionStart==='number'?[focused.selectionStart,focused.selectionEnd]:null;root.innerHTML=state.page==='editor'?editorPage():state.page==='templates'?templatesPage():state.page==='exports'?exportsPage():state.page==='settings'?settingsPage():projectsPage();if(state.page==='editor'){requestFrame();bindCanvas();}if(focusSelector){const target=$(focusSelector,root);if(target){target.focus({preventScroll:true});if(selection&&target.setSelectionRange)target.setSelectionRange(...selection);}}}
function projectsPage(){const items=state.projects.filter(p=>String(p.title).toLowerCase().includes(state.projectSearch.toLowerCase()));return `<div class="content"><div class="page-heading"><div><div class="eyebrow">YOUR CREATIVE WORKSPACE</div><h1>나의 프로젝트</h1><p class="description">긴 이야기에서, 오래 남을 한 장면을.</p></div><div class="row"><button data-action="project-import">${icon('folder',14)} 프로젝트 열기</button><button class="primary" data-action="upload">${icon('plus',15)} 새 프로젝트</button></div></div>${!state.projects.length?`<section class="welcome"><div><span class="badge amber">강의 · 주식 · ETF · 경제 콘텐츠를 위한</span><h2 style="margin-top:18px">지식의 깊이는 그대로,<br><span>쇼츠의 길이로.</span></h2><p>가로 강의와 차트는 온전히 담고, 핵심은 선명하게.<br>자막부터 제목, 세로 영상 출력까지 한곳에서 완성하세요.</p><button class="primary" data-action="upload">${icon('upload',15)} 첫 영상 등록하기</button><div class="steps"><span><b>1</b>영상 등록</span><span><b>2</b>자막과 구간 편집</span><span><b>3</b>세로 MP4 저장</span></div></div><div class="welcome-visual" aria-hidden="true">${[1,2,3].map((n)=>`<div class="mini-film"><b>${n===2?'숫자는 선명하게<br>핵심은 간결하게':'한 장의 차트,<br>하나의 인사이트'}</b><div class="mini-chart"><i></i><i></i><i></i><i></i></div><p>가로 자료를 온전히 담은<br>나만의 세로 콘텐츠</p></div>`).join('')}</div></section>`:''}<div class="toolbar"><div class="search grow">${icon('search')}<input id="project-search" placeholder="프로젝트 검색" aria-label="프로젝트 검색" value="${esc(state.projectSearch)}"></div><span class="muted" style="font-size:11px">총 ${state.projects.length}개</span><div class="grow"></div><button class="icon ${!state.list?'primary':''}" data-action="view-grid" title="카드 보기">${icon('grid',15)}</button><button class="icon ${state.list?'primary':''}" data-action="view-list" title="목록 보기">${icon('list',15)}</button></div><div id="project-list" class="project-grid ${state.list?'list':''}">${projectCards(items)}</div></div>`;}
function projectCards(items){if(!items.length)return `<div class="empty" style="grid-column:1/-1">${icon('folder')}<h3>${state.projects.length?'검색 결과가 없습니다':'아직 등록된 프로젝트가 없어요'}</h3><p>MP4 영상을 등록해 시작하세요. API 키 없이도 자막 편집과 영상 저장을 사용할 수 있습니다.</p><button data-action="upload">영상 선택</button></div>`;return items.map(p=>`<article class="project-card"><div class="thumbnail" data-open="${esc(p.id)}" role="button" tabindex="0" aria-label="${esc(p.title)} 열기"><img src="${esc(p.thumbnail||'/api/projects/'+p.id+'/thumbnail')}" alt="원본 영상 썸네일" loading="lazy"><span class="duration">${time(p.source?.duration??p.duration)}</span></div><div class="card-body"><div class="row between"><h3 data-open="${esc(p.id)}">${esc(p.title)}</h3><span class="badge">${p.clip_count??p.clips?.length??0}개 쇼츠</span></div><div class="card-meta"><span>${p.source?.width??p.width??'—'} × ${p.source?.height??p.height??'—'}</span><span>${p.created_at?new Date(p.created_at).toLocaleDateString('ko-KR',{timeZone:'Asia/Seoul'}):''}</span></div><div class="row"><button class="sm grow" data-open="${esc(p.id)}">프로젝트 열기 ${icon('arrow',12)}</button><button class="sm icon" data-action="duplicate-project" data-id="${esc(p.id)}" title="프로젝트 복제">${icon('copy',13)}</button><button class="sm icon ghost danger" data-action="delete-project" data-id="${esc(p.id)}" title="프로젝트 삭제">${icon('trash',13)}</button></div></div></article>`).join('');}
async function openProject(id){try{await flush();state.project=await api(`/api/projects/${id}`);state.clipId=state.project.clips[0]?.id;state.selectedClips=new Set(state.project.clips.map(c=>c.id));state.page='editor';state.time=0;try{const v=JSON.parse(localStorage.getItem('johnber-editor-view')||'{}');if(v.projectId===id){if(state.project.clips.some(c=>c.id===v.clipId))state.clipId=v.clipId;state.time=Math.max(0,Math.min(Number(v.time)||0,duration()));if(['title','subtitle','highlight','video','logo'].includes(v.element))state.element=v.element;if(['style','clip','ai'].includes(v.inspector))state.inspector=v.inspector;}}catch{}localStorage.setItem('johnber-page','editor');state.undo=[];state.redo=[];state.dirty=false;state.previewUrl=null;state.candidates=[];state.ranges=[];state.scope='clip';state.cueId=null;localStorage.setItem('johnber-last-project',id);render();}catch(e){toast(e.message,true);}}
function editorPage(){const p=state.project,c=clip();if(!p)return '<div class="loading-screen">프로젝트를 불러오는 중입니다.</div>';const jobs=state.jobs.filter(j=>j.project_id===p.id&&activeJob(j));return `<div class="editor-top"><div class="row"><button class="icon ghost" data-nav="projects" title="프로젝트 목록">${icon('back')}</button><div><div class="row"><div class="project-title" title="${esc(p.title)}">${esc(p.title)}</div><button class="icon ghost optional" data-action="rename-project" title="프로젝트 이름 변경">${icon('text',13)}</button></div><div id="save-status" class="save-status">모든 변경사항 저장됨</div></div></div><div class="row"><button class="icon ghost" data-action="undo" title="실행 취소 (Ctrl+Z)" ${!state.undo.length?'disabled':''}>${icon('undo')}</button><button class="icon ghost" data-action="redo" title="다시 실행 (Ctrl+Shift+Z)" ${!state.redo.length?'disabled':''}>${icon('redo')}</button><button data-action="save" class="sm">${icon('save',13)} <span class="save-label">저장</span></button><button data-action="preview" class="sm optional" ${!c?'disabled':''}>${icon('play',13)} 확정 미리보기</button><button class="primary sm" data-action="export" ${!c?'disabled':''}>${icon('export',14)} MP4 내보내기</button><button class="icon ghost optional" data-action="project-json" title="프로젝트 파일 다운로드">${icon('folder',14)}</button></div></div>${jobs.map(j=>`<div class="job-strip"><span class="spinner" style="width:12px;height:12px"></span><b>${names[j.kind]||j.kind}</b><span class="grow">${esc(j.stage||states[j.state])}</span><div class="progress ${j.progress==null?'unknown':''}"><i style="width:${Math.round((j.progress||0)*100)}%"></i></div><span>${j.progress==null?'처리 중':Math.round(j.progress*100)+'%'}</span><button class="sm ghost" data-action="cancel-job" data-id="${j.id}">취소</button></div>`).join('')}<div class="clip-bar"><span class="muted" style="font-size:10px;margin-right:5px">쇼츠 ${p.clips.length}</span>${p.clips.map((x,i)=>`<button class="clip-tab ${x.id===c?.id?'active':''}" data-clip="${x.id}" title="${esc(x.title)}">${String(i+1).padStart(2,'0')} · ${esc(x.title)}</button>`).join('')}<button class="sm ghost" data-action="new-clip">${icon('plus',12)} 수동 구간</button></div>${c?`<div class="editor-grid" style="${jobs.length?'height:calc(100vh - '+(196+jobs.length*45)+'px)':''}"><section class="panel preview-panel" aria-label="세로 영상 미리보기"><div class="panel-head"><h3>미리보기 <span class="badge" style="margin-left:5px">9:16</span></h3><span class="muted" style="font-size:10px">1080 × 1920</span></div><div class="preview-tools"><label class="check"><input type="checkbox" id="safe-toggle" ${state.safe?'checked':''}> 안전영역 가이드</label><button class="sm ghost" data-action="zoom-frame" title="미리보기 크게 보기">크게 보기 ↗</button></div><div class="preview-workspace"><div id="canvas" class="canvas" tabindex="0" aria-label="영상 요소를 드래그하거나 방향키로 이동"><div class="canvas-placeholder">${icon('video',25)}<span>정확한 프레임을 불러오는 중</span></div><img id="preview-frame" alt="최종 출력과 같은 렌더러로 만든 미리보기" draggable="false">${state.safe?'<div class="safe-guide"></div>':''}${elementBoxes(c)}<div id="boundary-warning"></div><div id="renderer-warnings"></div></div></div><div class="player-controls"><div class="row between"><button class="icon" data-action="play" title="확정 미리보기 재생">${icon('play',14)}</button><span id="player-time" class="player-time">${time(state.time,true)} / ${time(duration(c),true)}</span><button class="sm ghost" data-action="source-preview" title="원본 확인">원본 보기</button></div><input id="scrubber" type="range" min="0" max="${Math.max(.01,duration(c))}" step="0.033333" value="${state.time}" aria-label="편집본 시각"><div class="row between player-time"><span id="source-time">원본 ${time(sourceTime(),true)}</span><span>출력 ${Number(c.speed||1).toFixed(2)}×</span></div><p class="preview-note" style="margin-top:10px">드래그로 배치 · 방향키 1px · Shift + 방향키 10px<br>정지 화면과 MP4는 동일한 렌더러를 사용합니다.</p></div></section><section class="panel cue-panel" aria-label="전사문과 자막"><div class="panel-head"><h3>전사문 · 자막 <span class="badge" style="margin-left:5px">${p.cues.length}</span></h3><button class="sm ghost" data-action="subtitle-import">${icon('upload',12)} SRT / VTT</button></div><div class="cue-toolbar"><div class="search">${icon('search')}<input id="cue-search" placeholder="자막에서 검색" aria-label="자막 검색" value="${esc(state.cueSearch)}"></div><div class="row between"><button class="sm" data-action="new-cue">${icon('plus',11)} 수동 자막</button><button class="sm ghost" data-action="transcribe">${icon('spark',12)} 자동 전사</button><button class="sm ghost" data-action="restore-cues" ${!p.original_cues?.length?'disabled':''}>원문 복원</button></div></div><div class="panel-scroll cue-list" id="cue-list">${cueCards()}</div><div class="cue-hint">${icon('text',11)} 글자 수정은 영상·음성을 바꾸지 않습니다.<br>${icon('scissors',11)} <b>발화 구간 삭제</b>는 영상·음성·자막을 함께 제외합니다. 원본은 보존됩니다.</div></section><aside class="panel inspector-panel" aria-label="스타일과 구간 설정"><div class="inspector-tabs"><button data-inspector="style" class="${state.inspector==='style'?'active':''}">디자인 편집</button><button data-inspector="clip" class="${state.inspector==='clip'?'active':''}">구간 · 배속</button><button data-inspector="ai" class="${state.inspector==='ai'?'active':''}">${icon('spark',12)} 구간 추천</button></div><div class="panel-scroll" id="inspector">${inspectorContent()}</div></aside></div>`:`<div class="content"><div class="empty">${icon('scissors')}<h3>첫 번째 쇼츠 구간을 정해주세요</h3><p>시작·종료 시각과 제목을 입력하면 편집을 시작할 수 있습니다.</p><button class="primary" data-action="new-clip">수동 구간 만들기</button></div></div>`}`;}
function elementBoxes(c){return ['video','title','subtitle','logo'].map(key=>{const b=effectiveStyle(key);return `<div class="element-box ${state.element===key?'selected':''}" data-element="${key}" data-label="${({video:'원본 영상',title:'제목',subtitle:'자막',logo:'로고'})[key]}" style="left:${(b.x||0)/1080*100}%;top:${(b.y||0)/1920*100}%;width:${(b.w||1)/1080*100}%;height:${(b.h||1)/1920*100}%"><span class="resize-handle"></span></div>`;}).join('');}
function cueCards(){const c=clip(),p=state.project;if(!c)return '';const items=p.cues.map((q,i)=>({...q,index:i})).filter(q=>q.end>c.start&&q.start<c.end&&q.text.toLowerCase().includes(state.cueSearch.toLowerCase()));if(!items.length)return `<div class="empty" style="padding:35px 15px">${icon('text')}<h3>${p.cues.length?'이 구간에 표시할 자막이 없어요':'자막을 더하면 이야기가 선명해져요'}</h3><p>SRT/VTT를 불러오거나 직접 입력하세요.<br>외부 API 없이도 제작할 수 있습니다.</p><button class="sm" data-action="new-cue">수동 자막 추가</button></div>`;return items.map(q=>{const cut=(c.cuts||[]).some(x=>x.start<=q.start&&x.end>=q.end),active=sourceTime()>=q.start&&sourceTime()<q.end;return `<article class="cue-card ${active?'active':''} ${cut?'cut':''}" data-cue-id="${q.id}"><div class="cue-card-head"><span class="cue-index">${String(q.index+1).padStart(2,'0')}</span><button data-action="seek-cue" data-id="${q.id}" title="해당 문장으로 이동">${time(q.start,true)} → ${time(q.end,true)}</button>${cut?'<span class="badge red">발화 제외됨</span>':''}<button class="ghost" style="margin-left:auto;color:var(--muted)" data-action="cue-timing" data-id="${q.id}" title="자막 시간 수정">${icon('clock',11)}</button></div><textarea data-cue-text="${q.id}" aria-label="${q.index+1}번 자막 내용" spellcheck="false">${esc(q.text)}</textarea><div class="cue-card-footer"><label class="check"><input type="checkbox" data-cue-highlight="${q.id}" ${q.highlight&&q.highlight!=='False'?'checked':''}> 강조</label><div class="row" style="gap:2px"><button data-action="cue-style" data-id="${q.id}" title="현재 문장 스타일 편집">스타일</button><button data-action="highlight-cue" data-id="${q.id}" title="선택한 단어 또는 구절 강조">강조 구절</button><button data-action="split-cue" data-id="${q.id}" title="입력 커서에서 자막 분리">분리</button><button data-action="merge-cue" data-id="${q.id}">다음과 합치기</button><button class="danger" data-action="cut-cue" data-id="${q.id}" ${cut?'disabled':''}>발화 구간 삭제</button><button data-action="delete-cue" data-id="${q.id}" title="자막 글자만 제거">${icon('trash',10)}</button></div></div></article>`;}).join('');}
function numField(label,key,value,step=1,min,max){return `<label>${label}<input type="number" data-style="${key}" value="${Number(value??0)}" step="${step}" ${min!==undefined?`min="${min}"`:''} ${max!==undefined?`max="${max}"`:''}></label>`;}
function colorField(label,key,value){return `<label>${label}<input type="color" data-style="${key}" value="${/^#[\da-f]{6}$/i.test(value)?value:'#ffffff'}"></label>`;}
function inspectorContent(){const c=clip();if(!c)return '';if(state.inspector==='ai')return aiInspector();if(state.inspector==='clip')return clipInspector();const key=state.element,s=effectiveStyle(key),text=key!=='video',highlight=key==='highlight';return `<div class="element-tabs">${[['title','제목'],['subtitle','자막'],['highlight','강조'],['video','영상'],['logo','로고']].map(([k,n])=>`<button data-element-select="${k}" class="${state.element===k?'active':''}">${n}</button>`).join('')}</div>${['subtitle','highlight'].includes(key)?`<label style="margin-bottom:15px">스타일 적용 범위<select id="style-scope"><option value="clip" ${state.scope==='clip'?'selected':''}>현재 클립 전체</option><option value="cue" ${state.scope==='cue'?'selected':''} ${!selectedCue()?'disabled':''}>선택한 자막 문장</option></select></label>${state.scope==='cue'&&selectedCue()?`<div class="notice" style="margin-bottom:15px">${time(selectedCue().start,true)} · ${esc(selectedCue().text.slice(0,65))}<br>이 원문 문장의 개별 스타일이며, 같은 문장을 쓰는 다른 클립에도 반영됩니다.</div>`:''}`:''}${key==='title'?`<label>쇼츠 제목 · 직접 줄바꿈 가능<textarea id="clip-title" rows="3">${esc(c.title)}</textarea></label>`:''}${key==='logo'?`<label>로고 / 고정 문구<input data-style="text" value="${esc(s.text||'')}" placeholder="예: 존버나드"></label><div class="row" style="margin-top:10px"><button class="sm grow" data-action="logo-upload">${icon('upload',12)} 로고 이미지 등록</button>${s.asset_id?'<button class="sm" data-action="logo-remove">이미지 제거</button>':''}</div><p class="field-note">권한이 있는 PNG/JPG/WEBP를 사용하세요. 원본 비율을 보존합니다.</p>`:''}${key==='subtitle'?`<label class="check"><input type="checkbox" id="subtitles-enabled" ${c.subtitles_enabled!==false?'checked':''}> 추가 자막 표시</label><p class="field-note">원본에 자막이 있으면 추가 자막을 끌 수 있습니다.</p>`:''}${key==='video'?`<div class="notice">기본은 <b>원본 전체 보존 (Fit)</b>입니다. 확대 채우기는 선택한 상자에 맞춰 가장자리를 자릅니다.</div><label style="margin-top:13px">영상 맞춤<select data-style="fit"><option value="contain" ${s.fit!=='cover'?'selected':''}>원본 전체 보존 · Fit</option><option value="cover" ${s.fit==='cover'?'selected':''}>확대 채우기 · 가장자리 잘림</option></select></label>`:''}${highlight?`<div class="notice">강조한 단어·구절의 스타일입니다. 자막의 강조 구절 버튼으로 실제 원문에 있는 텍스트를 지정하세요. 위치와 줄바꿈은 일반 자막 배치를 따릅니다.</div>`:''}<div class="settings-section"><div class="section-title">${highlight?'강조 스타일':'위치와 크기'} ${!highlight?'<span class="muted">1080 × 1920 기준 px</span>':''}</div>${!highlight?`<div class="grid2">${numField('가로 위치 X','x',s.x)}${numField('세로 위치 Y','y',s.y)}${numField('너비','w',s.w,1,10,1080)}${numField('높이','h',s.h,1,10,1920)}</div><div class="row" style="margin-top:10px"><button class="sm grow" data-action="center-element">가운데 정렬</button><button class="sm ghost" data-action="reset-element">기본값 복구</button></div>`:''}${text?`<div class="stack" style="margin-top:${highlight?'0':'18px'}">${true?`<label>글꼴<select data-style="font">${fontOptions(s.font)}</select></label>`:''}<div class="grid2">${numField('글자 크기','size',s.size||52,1,10,220)}<label>굵기<select data-style="bold"><option value="true" ${s.bold!==false?'selected':''}>굵게</option><option value="false" ${s.bold===false?'selected':''}>보통</option></select></label></div><div class="grid2">${colorField('글자색','color',s.color||'#ffffff')}${!highlight?`<label>정렬<select data-style="align"><option value="center" ${s.align==='center'?'selected':''}>가운데</option><option value="left" ${s.align==='left'?'selected':''}>왼쪽</option><option value="right" ${s.align==='right'?'selected':''}>오른쪽</option></select></label>`:''}</div>${!highlight?`<div class="grid2">${numField('행간 배율','line_height',s.line_height||1.3,.05,.7,3)}${numField('자간 px','letter_spacing',s.letter_spacing||0,.5,-5,30)}</div>`:''}</div>`:''}</div>${text?`<div class="settings-section"><div class="section-title">외곽선과 배경</div><div class="grid2">${numField('외곽선 두께','stroke',s.stroke||0,.5,0,20)}${colorField('외곽선 색','stroke_color',s.stroke_color||'#000000')}${colorField('배경색','bg',s.bg||'#000000')}${numField('배경 불투명도','bg_opacity',s.bg_opacity||0,.05,0,1)}${numField('안쪽 여백','padding',s.padding||0,1,0,100)}${numField('모서리 반경','radius',s.radius||0,1,0,100)}</div><label class="check" style="margin-top:13px"><input type="checkbox" data-style="shadow" ${s.shadow?'checked':''}> 텍스트 그림자</label></div>`:''}<div class="settings-section"><div class="section-title">클립 전체 디자인</div><div class="grid2">${colorField('캔버스 배경','@background',c.style.background||'#101318')}<label>저장된 템플릿<select id="template-select"><option value="">템플릿 선택</option>${state.templates.map(t=>`<option value="${t.id}">${esc(t.name)} · v${t.version}</option>`).join('')}</select></label></div><div class="row" style="margin-top:12px"><button class="sm grow" data-action="save-template">${icon('save',12)} 템플릿으로 저장</button><button class="sm" data-action="apply-template">적용</button></div><div class="row" style="margin-top:10px"><button class="sm grow" data-action="background-upload">${icon('upload',12)} 배경 이미지 등록</button>${c.style.background_asset_id?'<button class="sm" data-action="background-remove">제거</button>':''}</div><button class="sm ghost" style="width:100%;margin-top:8px" data-action="update-template">선택 템플릿을 현재 디자인으로 갱신</button><p class="field-note">템플릿은 클립 기본 디자인을 저장합니다. 문장별 개별 스타일은 프로젝트에 보존합니다. 스타일 수정은 AI를 재호출하지 않으며 저장 후 미리보기를 갱신합니다.</p></div>`;}
function fontOptions(selected){const fs=state.health?.fonts;let items=[{id:'sans',name:'기본 한글 산세리프'},{id:'serif',name:'한글 명조'}];if(fs&&!Array.isArray(fs))items=Object.entries(fs).filter(([id])=>['sans','serif'].includes(id)).map(([id,value])=>({id,name:typeof value==='string'?value:value.family||id}));if(Array.isArray(fs))items=fs.map(f=>typeof f==='string'?{id:f,name:f}:{id:f.id||f.key||f.name,name:f.name||f.label||f.id});return items.map(f=>`<option value="${esc(f.id)}" ${f.id===(selected||'sans')?'selected':''}>${esc(f.name)}</option>`).join('');}
function clipInspector(){const c=clip();return `<div class="section-title">원본에서 선택한 구간 <span class="badge amber">비파괴 편집</span></div><div class="grid2"><label>시작 (원본 초)<input id="clip-start" type="number" min="0" max="${state.project.source.duration}" step=".01" value="${c.start}"></label><label>종료 (원본 초)<input id="clip-end" type="number" min="0" max="${state.project.source.duration}" step=".01" value="${c.end}"></label></div><label style="margin-top:16px">재생 속도 · 음정 보존<select id="clip-speed">${[.75,1,1.1,1.25,1.5,1.75,2].map(v=>`<option value="${v}" ${Math.abs((c.speed||1)-v)<.001?'selected':''}>${v.toFixed(2)} ×</option>`).join('')}</select></label><div class="notice" style="margin-top:15px">원본 구간 ${time(c.end-c.start,true)} → 편집본 <b>${time(duration(c),true)}</b><br>영상·음성·자막이 같은 시간 매핑을 사용합니다.</div><div class="settings-section"><div class="section-title">삭제한 발화 · 무음 <span class="badge">${(c.cuts||[]).length}</span></div>${(c.cuts||[]).map((x,i)=>`<div class="range-row"><span class="grow">${time(x.start,true)} – ${time(x.end,true)}</span><button class="sm ghost" data-action="restore-cut" data-index="${i}">복원</button></div>`).join('')||'<p class="field-note">제외한 구간이 없습니다. 원본 파일은 항상 보존됩니다.</p>'}<div class="row" style="margin-top:13px"><button class="sm grow" data-action="add-cut">${icon('scissors',12)} 삭제 구간 추가</button><button class="sm" data-action="silence">무음 감지</button></div></div>${state.ranges.length?`<div class="settings-section"><div class="section-title">감지된 무음 후보 <span class="badge">${state.ranges.length}</span></div><p class="field-note">아직 영상에 반영하지 않았습니다. 확인 후 적용하세요.</p>${state.ranges.map(x=>`<div class="range-row"><span>${time(x.start,true)} – ${time(x.end,true)}</span><span class="muted" style="margin-left:auto">${(x.end-x.start).toFixed(2)}초</span></div>`).join('')}<button class="sm primary" style="margin-top:12px" data-action="apply-silence">후보를 삭제 구간에 추가</button></div>`:''}<div class="settings-section"><div class="section-title">클립 관리</div><div class="row"><button class="sm grow" data-action="duplicate-clip">${icon('copy',12)} 클립 복제</button><button class="sm danger" data-action="delete-clip">클립 삭제</button></div></div>`;}
function aiInspector(){const ai=state.health?.ai||{};return `<div class="section-title">이야기의 핵심을 찾는 도우미</div><div class="notice">${ai.remote_key?'외부 AI가 연결되어 있습니다. 호출 전 데이터 전송과 비용 확인이 필요합니다.':'외부 AI 미연결 · SRT와 수동 편집은 계속 사용할 수 있습니다.'}</div><div class="stack" style="margin-top:17px"><label>추천 방식<select id="recommend-provider"><option value="rules">로컬 규칙 기반 · API 비용 없음</option><option value="remote" ${!ai.remote_key?'disabled':''}>외부 AI · ${esc(ai.chat_model||'서버 설정 모델')} ${!ai.remote_key?'(미연결)':''}</option></select></label><div class="grid2"><label>최소 길이 (초)<input id="recommend-min" type="number" value="30" min="3" max="600"></label><label>최대 길이 (초)<input id="recommend-max" type="number" value="60" min="3" max="600"></label></div><label>최대 후보 수<input id="recommend-count" type="number" value="5" min="1" max="20"></label><button class="primary" data-action="recommend" ${!state.project.cues.length?'disabled':''}>${icon('spark',14)} 구간 후보 찾기</button><p class="field-note">규칙 기반 후보는 문장·길이 기준이며 AI 결과가 아닙니다. 점수는 내부 평가로, 조회수나 흥행 확률을 뜻하지 않습니다.</p></div><div id="candidates">${state.candidates.map((x,i)=>`<article class="candidate"><div class="row between"><span class="badge amber">후보 ${i+1}</span><span class="score">${x.score!=null?'내부 점수 '+esc(x.score):''}</span></div><h4>${esc(x.title||x.title_candidate||'추천 구간')}</h4><small>${time(x.start,true)} – ${time(x.end,true)} · ${(x.end-x.start).toFixed(1)}초</small><p>${esc(x.summary||'')}</p><p>${esc(x.reason||x.recommendation_reason||'')}</p>${(x.warnings||[]).length?`<div class="notice">${esc(x.warnings.join(' · '))}</div>`:''}<button class="sm" style="width:100%;margin-top:10px" data-action="apply-candidate" data-index="${i}">${icon('plus',12)} 편집할 쇼츠로 추가</button></article>`).join('')}</div>${state.candidates.length?'<button class="sm" style="width:100%;margin-top:14px" data-action="apply-all-candidates">모든 후보를 쇼츠로 추가</button>':''}`;}
function templatesPage(){return `<div class="content"><div class="page-heading"><div><div class="eyebrow">YOUR SIGNATURE STYLE</div><h1>템플릿 · 스타일</h1><p class="description">한 번 만든 나만의 디자인으로, 여러 편을 일관되게.</p></div><div class="row"><button data-action="template-import">${icon('upload',14)} JSON 가져오기</button><button class="primary" data-action="new-template">${icon('plus',14)} 템플릿 만들기</button></div></div><div class="notice" style="margin-bottom:25px">템플릿은 레이아웃·자막·강조 스타일을 담은 버전 데이터입니다. 템플릿을 바꿔도 이미 편집한 클립은 자동으로 바뀌지 않습니다.</div><div class="template-grid">${state.templates.map(t=>`<article class="template-card"><div class="template-preview" data-action="template-info" data-id="${t.id}">${templateMini(t.style)}</div><div class="card-body"><div class="row between"><h3>${esc(t.name)}</h3><span class="badge">v${t.version}</span></div><p class="field-note">원본 전체 보존 · 1080 × 1920</p><div class="template-actions"><button class="sm grow" data-action="template-apply-dialog" data-id="${t.id}">클립에 적용</button><button class="icon sm" data-action="template-rename" data-id="${t.id}" title="이름 변경">${icon('text',12)}</button><button class="icon sm" data-action="template-copy" data-id="${t.id}" title="복제">${icon('copy',12)}</button><button class="icon sm" data-action="template-download" data-id="${t.id}" title="JSON 저장">${icon('export',12)}</button><button class="icon sm ghost danger" data-action="template-delete" data-id="${t.id}" title="삭제">${icon('trash',12)}</button></div></div></article>`).join('')||'<div class="empty"><h3>저장된 템플릿이 없습니다.</h3><p>편집기의 디자인을 템플릿으로 저장하세요.</p></div>'}</div></div>`;}
function templateMini(s={}){const box=(b={})=>`left:${(b.x||0)/1080*100}%;top:${(b.y||0)/1920*100}%;width:${(b.w||900)/1080*100}%;height:${(b.h||200)/1920*100}%;`;return `<div class="template-canvas" style="background:${esc(s.background||'#101318')}"><div class="t-title" style="${box(s.title)}color:${esc(s.title?.color||'#ffffff')};font-size:${(s.title?.size||66)/1080*106}px">깊이 있는 지식,<br>짧고 선명하게</div><div class="t-video" style="${box(s.video)}">원본 전체 보존</div><div class="t-subtitle" style="${box(s.subtitle)}color:${esc(s.subtitle?.color||'#ffffff')}">나만의 이야기를<br><span style="color:${esc(s.highlight?.color||'#ffc76b')}">전하는 순간</span></div></div>`;}
function exportsPage(){const jobs=[...state.jobs].sort((a,b)=>Date.parse(b.created_at||b.updated_at||0)-Date.parse(a.created_at||a.updated_at||0));return `<div class="content"><div class="page-heading"><div><div class="eyebrow">READY TO SHARE</div><h1>완성 영상 · 작업</h1><p class="description">실제 처리 상태와 완성된 파일을 확인하세요.</p></div><button data-action="refresh-jobs">${icon('clock',14)} 상태 새로고침</button></div><div class="stack">${jobs.map(jobCard).join('')||`<div class="empty">${icon('export')}<h3>아직 내보낸 영상이 없습니다</h3><p>프로젝트에서 클립을 편집하고 MP4 내보내기를 눌러주세요. 완성된 파일만 다운로드할 수 있습니다.</p><button data-nav="projects">프로젝트로 이동</button></div>`}</div></div>`;}
function jobCard(j){return `<article class="job-card" data-job-id="${j.id}"><div class="row between wrap"><div class="row"><div style="color:var(--accent)">${icon(j.kind==='render'?'video':j.kind==='recommend'?'spark':'clock',23)}</div><div><h3>${names[j.kind]||esc(j.kind)}</h3><p class="field-note" style="margin-top:4px">${esc(j.stage||'')} · ${j.created_at?new Date(j.created_at).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'}):esc(j.id.slice(0,8))}</p></div></div><div class="row"><span class="badge ${j.state==='succeeded'?'green':j.state==='failed'?'red':activeJob(j)?'amber':''}">${states[j.state]||esc(j.state)} ${j.progress!=null&&activeJob(j)?Math.round(j.progress*100)+'%':''}</span>${activeJob(j)?`<button class="sm" data-action="cancel-job" data-id="${j.id}">취소</button>`:['failed','cancelled','interrupted'].includes(j.state)?`<button class="sm" data-action="retry-job" data-id="${j.id}">재시도</button>`:''}<button class="sm ghost" data-open="${j.project_id}">프로젝트 열기</button></div></div>${activeJob(j)?`<div class="progress ${j.progress==null?'unknown':''}"><i style="width:${Math.round((j.progress||0)*100)}%"></i></div>`:''}${j.result?.applied===false&&j.result?.cues?`<div class="notice" style="margin-top:14px">${esc(j.result.message||'전사 결과를 보관했습니다. 기존 자막 변경과 충돌하여 자동 적용하지 않았습니다.')}<br><button class="sm" style="margin-top:8px" data-action="review-transcript" data-id="${j.id}">전사 결과 검토·적용</button></div>`:''}${j.error?`<div class="notice error" style="margin-top:14px">${esc(typeof j.error==='object'?j.error.message||JSON.stringify(j.error):j.error)}</div>`:''}${(j.artifacts||[]).map(a=>`<div class="artifact">${icon(a.kind==='mp4'?'video':'export',17)}<span class="grow">${esc(a.filename)}</span><span class="badge">${esc(a.kind?.toUpperCase())}</span><a class="button" href="${esc(a.url||'/api/artifacts/'+a.id)}" download>${icon('export',13)} 다운로드</a>${a.kind==='mp4'?`<button class="sm" data-action="artifact-play" data-url="${esc(a.url||'/api/artifacts/'+a.id)}" data-name="${esc(a.filename)}">재생</button>`:''}</div>`).join('')}${j.log?`<details style="margin-top:12px"><summary class="muted" style="font-size:11px;cursor:pointer">작업 로그</summary><pre style="font-size:10px;white-space:pre-wrap;line-height:1.8">${esc(Array.isArray(j.log)?j.log.join('\n'):j.log)}</pre></details>`:''}</article>`;}
function settingsPage(){const h=state.health||{},a=h.ai||{};return `<div class="content"><div class="page-heading"><div><div class="eyebrow">LOCAL FIRST, ALWAYS</div><h1>스튜디오 설정</h1><p class="description">내 컴퓨터의 처리 환경과 선택적 AI 연결 상태입니다.</p></div><button data-action="refresh-health">연결 상태 확인</button></div><div class="settings-grid"><section class="settings-card"><h3>${icon('settings',17)} 로컬 제작 환경</h3><div class="settings-line"><span>FFmpeg · 영상 인코딩</span><span class="badge ${h.ffmpeg?'green':'red'}">${h.ffmpeg?'사용 가능':'설치 필요'}</span></div><div class="settings-line"><span>기본 출력</span><span class="muted">1080 × 1920 · 30fps</span></div><div class="settings-line"><span>인코딩</span><span class="muted">H.264 / AAC</span></div><div class="settings-line"><span>기본 영상 배치</span><span class="muted">전체 원본 보존 (Fit)</span></div><p class="field-note">원본·프로젝트·완성 파일은 서버 실행 컴퓨터에 저장됩니다. 프로젝트 JSON은 편집 데이터를 담으며 원본 영상을 포함하지 않습니다.</p></section><section class="settings-card"><h3>${icon('spark',17)} 선택적 AI 연결</h3><div class="settings-line"><span>외부 API 인증</span><span class="badge ${a.remote_key?'green':''}">${a.remote_key?'서버에 설정됨':'미연결'}</span></div><div class="settings-line"><span>구간 추천 모델</span><span class="muted">${esc(a.chat_model||'미설정')}</span></div><div class="settings-line"><span>외부 전사 모델</span><span class="muted">${esc(a.stt_model||'미설정')}</span></div><div class="settings-line"><span>로컬 전사 엔진</span><span class="badge ${a.local_stt?'green':''}">${a.local_stt?'사용 가능':'선택 설치'}</span></div><div class="notice" style="margin-top:17px">외부 API는 사용량에 따라 비용이 발생할 수 있습니다. 비용 미확인 · 호출 전에 보낼 데이터와 모델을 확인합니다. 키는 서버의 .env에서 설정하며 브라우저에 저장하지 않습니다.</div></section><section class="settings-card"><h3>${icon('text',17)} 글꼴과 정확한 미리보기</h3><p class="description">서버에 설치된 글꼴로 제목과 자막을 렌더링합니다. 미리보기와 MP4에 같은 글꼴·좌표·줄바꿈을 사용합니다.</p><div class="row wrap" style="margin-top:17px">${Object.entries(h.fonts||{}).filter(([k])=>['sans','serif'].includes(k)).map(([k,f])=>`<span class="badge">${esc(typeof f==='string'?f:f.family||k)}</span>`).join('')||'<span class="badge">기본 한글 글꼴</span>'}</div>${h.fonts?.warnings?.length?`<div class="notice error" style="margin-top:14px">${esc(h.fonts.warnings.join(' · '))}</div>`:''}<p class="field-note">글꼴 파일이나 라이선스를 참고 서비스에서 복제하지 않습니다. 글리프 누락이 보이면 README의 한글 글꼴 설치 안내를 확인하세요.</p></section><section class="settings-card"><h3>${icon('folder',17)} 안전한 반복 제작</h3><p class="description">자막 글자 수정은 음성을 바꾸지 않습니다. 삭제 구간·배속·스타일은 프로젝트 데이터로 저장하고 원본을 유지합니다.</p><div class="divider"></div><p class="field-note">자막 색·디자인 변경은 전사나 AI 분석을 재호출하지 않습니다. 저장된 전사·분석 캐시는 같은 원본과 설정에서 재사용합니다. 자동 게시와 공개 배포 기능은 포함하지 않습니다.</p></section></div></div>`;}
function setInspector(){const el=$('#inspector');if(el)el.innerHTML=inspectorContent();$$('[data-inspector]').forEach(x=>x.classList.toggle('active',x.dataset.inspector===state.inspector));}
function scheduleFrame(){clearTimeout(frameTimer);frameTimer=setTimeout(async()=>{try{await flush();requestFrame();}catch{}},850);}
function requestFrame(){const p=state.project,c=clip(),img=$('#preview-frame');if(state.page!=='editor'||!p||!c||!img)return;const seq=++state.frameSeq;const src=`/api/projects/${p.id}/frame?clip_id=${encodeURIComponent(c.id)}&time=${Math.min(state.time,Math.max(0,duration(c)-.001))}&rev=${p.revision||0}`;const loader=new Image();loader.onload=()=>{if(seq!==state.frameSeq||!$('#preview-frame'))return;$('#preview-frame').src=src;$('.canvas-placeholder')?.classList.add('hide');api(`/api/projects/${p.id}/frame-info?clip_id=${encodeURIComponent(c.id)}&time=${Math.min(state.time,Math.max(0,duration(c)-.001))}`).then(info=>{const el=$('#renderer-warnings');if(el&&seq===state.frameSeq)el.innerHTML=info.warnings?.length?`<div class="overlap-warning" style="bottom:30px">${esc(info.warnings.join(' · '))}</div>`:'';}).catch(()=>{});};loader.onerror=()=>{if(seq===state.frameSeq)toast('프레임을 읽지 못했습니다. 저장 상태와 서버 로그를 확인하세요.',true);};loader.src=src;boundaryWarning();}
function boundaryWarning(){const c=clip(),el=$('#boundary-warning');if(!c||!el)return;const out=['title','subtitle','video','logo'].filter(k=>{const s=c.style[k];return s&&(s.x<0||s.y<0||s.x+s.w>1080||s.y+s.h>1920);});el.innerHTML=out.length?'<div class="overlap-warning">요소가 출력 경계를 벗어났습니다. 위치와 크기를 확인하세요.</div>':'';}
function selectElement(k){state.element=k;state.inspector='style';persistView();setInspector();$$('.element-box').forEach(el=>el.classList.toggle('selected',el.dataset.element===k));}
function bindCanvas(){const canvas=$('#canvas');if(!canvas)return;canvas.addEventListener('pointerdown',e=>{const box=e.target.closest('.element-box');if(!box||state.previewUrl&&$('#preview-video'))return;e.preventDefault();const key=box.dataset.element;selectElement(key);canvas.focus();const resizing=e.target.classList.contains('resize-handle'),orig=clone(effectiveStyle(key)),r=canvas.getBoundingClientRect(),x=e.clientX,y=e.clientY;let moved=false;box.setPointerCapture(e.pointerId);const move=ev=>{if(!moved){record();moved=true;}const dx=(ev.clientX-x)/r.width*1080,dy=(ev.clientY-y)/r.height*1920,s=styleTarget(key);if(resizing){s.w=Math.max(30,Math.min(1080,Math.round(orig.w+dx)));s.h=Math.max(30,Math.min(1920,Math.round(orig.h+dy)));}else{s.x=Math.round(orig.x+dx);s.y=Math.round(orig.y+dy);if(Math.abs(s.x+orig.w/2-540)<12)s.x=Math.round(540-orig.w/2);}const effective=effectiveStyle(key);box.style.left=effective.x/1080*100+'%';box.style.top=effective.y/1920*100+'%';box.style.width=effective.w/1080*100+'%';box.style.height=effective.h/1920*100+'%';boundaryWarning();};const up=()=>{box.removeEventListener('pointermove',move);box.removeEventListener('pointerup',up);box.removeEventListener('pointercancel',up);if(moved){changed();setInspector();}};box.addEventListener('pointermove',move);box.addEventListener('pointerup',up);box.addEventListener('pointercancel',up);});}
function seek(t){state.time=Math.max(0,Math.min(duration(),t));persistView();const s=$('#scrubber');if(s)s.value=state.time;const tt=$('#player-time');if(tt)tt.textContent=`${time(state.time,true)} / ${time(duration(),true)}`;const st=$('#source-time');if(st)st.textContent='원본 '+time(sourceTime(),true);const v=$('#preview-video');if(v){if(Math.abs(v.currentTime-state.time)>.15)v.currentTime=state.time;return;}clearTimeout(frameTimer);frameTimer=setTimeout(requestFrame,90);$$('.cue-card').forEach(el=>{const q=state.project.cues.find(x=>x.id===el.dataset.cueId);el.classList.toggle('active',q&&sourceTime()>=q.start&&sourceTime()<q.end);});}
function modal(title,body,buttons=[]){const d=$('#modal');if(d.open)d.close();d.innerHTML=`<div class="modal-head"><h3>${title}</h3><button class="icon ghost" data-action="close-modal" title="닫기">${icon('close',16)}</button></div><div class="modal-body">${body}</div><div class="modal-foot">${buttons.map((b,i)=>`<button class="${b.primary?'primary':''} ${b.danger?'danger':''}" data-modal-button="${i}">${b.label}</button>`).join('')}</div>`;buttons.forEach((b,i)=>$(`[data-modal-button="${i}"]`,d).addEventListener('click',async e=>{const btn=e.currentTarget;try{btn.disabled=true;await b.run?.();}catch(err){toast(err.message,true);}finally{if(btn.isConnected)btn.disabled=false;}}));d.showModal();return d;}
function closeModal(){$('#modal').close();const v=$('video',$('#modal'));if(v)v.pause();}
function confirmAction(title,message,run,label='확인'){modal(title,`<p>${message}</p>`,[{label:'취소',run:closeModal},{label,primary:true,run:async()=>{await run();closeModal();}}]);}
function downloadJSON(obj,name){const u=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function uploadDialog(){modal('새 프로젝트 만들기',`<p>강의나 해설 원본 영상을 선택하세요. 업로드한 원본은 보존하고 편집 결과를 별도 MP4로 저장합니다.</p><div class="upload-drop" data-action="choose-video" tabindex="0" role="button">${icon('upload',32)}<strong>클릭해서 영상 선택</strong><span>MP4 · MOV · 디코딩 가능한 영상 파일<br>파일을 여기로 끌어 놓을 수도 있어요.</span></div><p class="field-note" style="margin-top:15px">화면 참고자료가 아닌, 쇼츠를 제작할 권한이 있는 원본을 사용하세요. 등록은 로컬 처리이며 외부 AI를 호출하지 않습니다.</p>`,[{label:'취소',run:closeModal}]);const drop=$('.upload-drop');drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('drag');});drop.addEventListener('dragleave',()=>drop.classList.remove('drag'));drop.addEventListener('drop',e=>{e.preventDefault();if(e.dataTransfer.files[0])uploadVideo(e.dataTransfer.files[0]);});}
function uploadVideo(file){if(!file)return;const d=$('#modal');d.innerHTML=`<div class="modal-head"><h3>원본 영상을 등록하고 있어요</h3></div><div class="modal-body"><div class="row"><span class="spinner"></span><strong>${esc(file.name)}</strong></div><p style="margin-top:15px">${bytes(file.size)} · 업로드 후 실제 길이·해상도·음성 트랙을 검사합니다.</p><div id="upload-progress" class="progress unknown"><i></i></div><p id="upload-stage" class="field-note">원본 업로드 중</p></div><div class="modal-foot"><button id="cancel-upload">업로드 취소</button></div>`;if(!d.open)d.showModal();const form=new FormData();form.append('file',file);form.append('title',file.name.replace(/\.[^.]+$/,''));const xhr=new XMLHttpRequest();xhr.open('POST','/api/projects');xhr.upload.onprogress=e=>{if(e.lengthComputable){const progress=$('#upload-progress');if(progress){progress.classList.remove('unknown');$('i',progress).style.width=Math.round(e.loaded/e.total*100)+'%';}if(e.loaded===e.total){$('#upload-stage').textContent='업로드 완료 · 영상 메타데이터 검사 중';$('#upload-progress').classList.add('unknown');}}};xhr.onload=()=>{if(xhr.status>=200&&xhr.status<300){const p=JSON.parse(xhr.responseText);closeModal();openProject(p.id);toast('원본 등록이 완료되었습니다. 자막과 쇼츠 구간을 추가하세요.');}else{let error;try{error=JSON.parse(xhr.responseText).detail;}catch{error='업로드를 완료하지 못했습니다.';}modal('원본 등록 실패',`<div class="notice error">${esc(error)}</div><p style="margin-top:15px">손상되거나 지원하지 않는 영상인지 확인하고 다시 시도해 주세요.</p>`,[{label:'닫기',run:closeModal},{label:'다른 파일 선택',primary:true,run:()=>$('#video-upload').click()}]);}};xhr.onerror=()=>{toast('서버 연결이 끊겼습니다. 실행 창을 확인하고 다시 시도해 주세요.',true);closeModal();};xhr.onabort=()=>{toast('업로드를 취소했습니다.');closeModal();};$('#cancel-upload').onclick=()=>xhr.abort();xhr.send(form);}
function newClipDialog(){if(!state.project)return;const d=state.project.source.duration;modal('수동 쇼츠 구간 만들기',`<p>원본 시각을 초 단위로 입력하세요. 처음에는 원본 전체가 보이는 강의형 레이아웃을 적용합니다.</p><div class="stack"><label>제목<textarea id="new-clip-title" rows="2" placeholder="이 쇼츠에서 전할 핵심 이야기"></textarea></label><div class="grid2"><label>시작 (원본 초)<input id="new-clip-start" type="number" min="0" max="${d}" step=".01" value="0"></label><label>종료 (원본 초)<input id="new-clip-end" type="number" min="0" max="${d}" step=".01" value="${Math.min(d,60)}"></label></div><div class="notice">원본 길이 ${time(d,true)} · 구간과 자막은 나중에 다시 조정할 수 있습니다.</div></div>`,[{label:'취소',run:closeModal},{label:'쇼츠 만들기',primary:true,run:async()=>{await flush();const start=Number($('#new-clip-start').value),end=Number($('#new-clip-end').value),title=$('#new-clip-title').value.trim()||'새로운 쇼츠';if(start<0||end<=start||end>d)throw new Error('시작·종료 시각이 원본 범위 안에 있는지 확인하세요.');state.project=await api(`/api/projects/${state.project.id}/clips`,{method:'POST',body:{title,start,end}});state.clipId=state.project.clips.at(-1).id;state.selectedClips.add(state.clipId);state.time=0;closeModal();renderPage();toast('새 쇼츠 구간을 만들었습니다.');}}]);}
function newCueDialog(){const c=clip();if(!c)return;const at=sourceTime();modal('수동 자막 추가',`<p>원본 영상의 시간 기준입니다. 입력한 자막만 추가되며 음성이나 영상은 바뀌지 않습니다.</p><div class="stack"><div class="grid2"><label>시작 (원본 초)<input id="new-cue-start" type="number" min="0" step=".01" value="${at.toFixed(2)}"></label><label>종료 (원본 초)<input id="new-cue-end" type="number" min="0" step=".01" value="${Math.min(at+3,c.end).toFixed(2)}"></label></div><label>자막 내용<textarea id="new-cue-text" rows="4" placeholder="실제 발화 내용을 입력하세요. Enter로 줄바꿈"></textarea></label></div>`,[{label:'취소',run:closeModal},{label:'자막 추가',primary:true,run:async()=>{const start=Number($('#new-cue-start').value),end=Number($('#new-cue-end').value),text=$('#new-cue-text').value.trim();if(!text||start<0||end<=start||end>state.project.source.duration)throw new Error('내용과 시작·종료 시각을 확인하세요.');record();state.project.cues.push({id:crypto.randomUUID(),start,end,text,highlight:''});state.project.cues.sort((a,b)=>a.start-b.start);changed();await flush();closeModal();renderPage();}}]);}
function exportDialog(){const p=state.project;if(!p?.clips.length)return;modal('MP4 내보내기',`<p>제목·자막·삭제 구간·배속을 반영해 실제 세로 영상을 만듭니다. 여러 클립을 선택하면 개별 MP4와 일괄 ZIP을 함께 저장합니다.</p>${p.clips.map(c=>`<div class="modal-checkbox"><input id="export-${c.id}" class="export-check" type="checkbox" value="${c.id}" ${state.selectedClips.has(c.id)?'checked':''}><label for="export-${c.id}">${esc(c.title)}<small>${time(duration(c),true)} · ${Number(c.speed||1).toFixed(2)}×</small></label></div>`).join('')}<div class="notice" style="margin-top:15px">1080 × 1920 · 30fps · H.264 + AAC<br>로컬 CPU 처리입니다. 원본이 길거나 자막이 많으면 시간이 걸릴 수 있습니다. AI API는 호출하지 않습니다.</div>`,[{label:'취소',run:closeModal},{label:'선택한 쇼츠 내보내기',primary:true,run:async()=>{const ids=$$('.export-check:checked').map(x=>x.value);if(!ids.length)throw new Error('내보낼 클립을 하나 이상 선택하세요.');state.selectedClips=new Set(ids);await startJob('render',{clip_ids:ids});closeModal();nav('exports');}}]);}
async function startJob(kind,options={}){await flush();const body={kind,clip_ids:options.clip_ids||[clip()?.id].filter(Boolean),settings:options.settings||{}};const j=await api(`/api/projects/${state.project.id}/jobs`,{method:'POST',body});state.jobs=state.jobs.filter(x=>x.id!==j.id).concat(j);toast(`${names[kind]||kind} 작업을 시작했습니다.`);if(state.page==='editor')renderPage();return j;}
function externalConsent(kind,settings,callback){const ai=state.health?.ai||{},isSTT=kind==='transcribe';modal('외부 AI 사용 확인',`<p>${isSTT?'원본에서 추출한 음성':'현재 교정된 전사문과 시간정보'}을 서버에 설정한 외부 AI 제공자에게 전송합니다.</p><div class="stack"><div class="notice">제공자: OpenAI 호환 서버 · 모델 ${esc(isSTT?ai.stt_model:ai.chat_model)}<br>전송 범위: ${isSTT?'전사에 필요한 음성':'구간 추천에 필요한 자막 텍스트·시각'}<br>예상 사용량: ${isSTT?time(state.project.source.duration)+' 분량의 음성':state.project.cues.reduce((a,q)=>a+q.text.length,0).toLocaleString()+'자 전사문'}<br><b>비용 미확인</b> · 제공자의 최신 요금과 계정 한도를 확인하세요.</div><label class="check"><input id="external-consent" type="checkbox"> 데이터 전송과 발생 가능한 API 비용에 동의합니다.</label></div>`,[{label:'취소',run:closeModal},{label:'동의하고 실행',primary:true,run:async()=>{if(!$('#external-consent').checked)throw new Error('외부 전송과 비용 동의를 확인해주세요.');await callback({...settings,consent_external:true});closeModal();}}]);}
function transcribeDialog(){const a=state.health?.ai||{};modal('한국어 자동 전사',`<p>원본 음성에서 시간정보가 있는 자막을 만듭니다. 기존 원문과 같은 설정의 결과는 캐시를 재사용합니다. 인식한 숫자·티커·고유명사는 직접 검토하세요.</p><div class="stack"><label>처리 방식<select id="transcribe-provider"><option value="local" ${!a.local_stt?'disabled':''}>로컬 Whisper · ${a.local_stt?'외부 API 비용 없음':'엔진 설치 필요'}</option><option value="remote" ${!a.remote_key?'disabled':''}>외부 API · ${a.remote_key?esc(a.stt_model||'서버 설정 모델'):'키 미연결'}</option></select></label><label>사용자 사전 · 쉼표로 구분<textarea id="transcribe-dictionary" rows="2">SOXL, TQQQ, SCHD, SOXX, SMH, 엔비디아, 커버드콜, 분배금</textarea></label><label class="check"><input id="model-consent" type="checkbox"> 로컬 모델이 없으면 공식 모델 다운로드를 허용합니다.</label><p class="field-note">사전은 인식 보조용입니다. 숫자와 고유명사를 무조건 치환하지 않습니다. 로컬 모델은 처음 사용할 때 다운로드와 저장 공간이 필요할 수 있습니다.</p>${!a.local_stt&&!a.remote_key?'<div class="notice">자동 전사 엔진이 연결되지 않았습니다. SRT/VTT 가져오기 또는 수동 자막으로 계속 제작할 수 있습니다. README에서 로컬 전사 엔진 설치 방법을 확인하세요.</div>':''}</div>`,[{label:'닫기',run:closeModal},{label:'전사 시작',primary:true,run:async()=>{const provider=$('#transcribe-provider').value;if((provider==='local'&&!a.local_stt)||(provider==='remote'&&!a.remote_key))throw new Error('선택한 전사 엔진이 연결되지 않았습니다.');const settings={provider,language:'ko',dictionary:$('#transcribe-dictionary').value,consent_model_download:$('#model-consent').checked};if(provider==='remote')externalConsent('transcribe',settings,s=>startJob('transcribe',{settings:s}));else {await startJob('transcribe',{settings});closeModal();}}}]);}
function templateApplyDialog(id){const t=state.templates.find(x=>x.id===id);if(!t)return;if(!state.project?.clips.length){toast('먼저 프로젝트를 열고 클립을 만들어 주세요.');return;}modal('템플릿 적용 범위',`<p><b>${esc(t.name)} · v${t.version}</b>을 선택한 클립에 복사합니다. 적용 이후 템플릿을 수정해도 이 클립은 자동 변경되지 않습니다.</p>${state.project.clips.map(c=>`<label class="modal-checkbox"><input class="template-clip-check" type="checkbox" value="${c.id}" ${c.id===state.clipId?'checked':''}><span>${esc(c.title)}</span></label>`).join('')}<label style="margin-top:15px">기존 사용자 편집 처리<select id="template-mode"><option value="all">클립 기본 디자인 덮어쓰기 · 문장별 스타일/텍스트/구간 유지</option><option value="colors">색상만 적용 · 좌표/크기/줄바꿈 유지</option></select></label>`,[{label:'취소',run:closeModal},{label:'선택한 클립에 적용',primary:true,run:async()=>{const ids=$$('.template-clip-check:checked').map(x=>x.value),mode=$('#template-mode').value;if(!ids.length)throw new Error('적용할 클립을 선택하세요.');record();for(const c of state.project.clips.filter(x=>ids.includes(x.id))){if(mode==='all')c.style=clone(t.style);else {c.style.background=t.style.background;for(const k of ['title','subtitle','highlight','logo'])for(const prop of ['color','bg','stroke_color','bg_opacity'])if(t.style[k]?.[prop]!==undefined)c.style[k][prop]=t.style[k][prop];}c.template_id=t.id;c.template_version=t.version;}changed();await flush();closeModal();if(state.page==='editor')renderPage();toast(`${ids.length}개 클립에 템플릿을 적용했습니다.`);}}]);}
function promptName(title,value,callback){modal(title,`<label>이름<input id="name-input" value="${esc(value)}" maxlength="180"></label>`,[{label:'취소',run:closeModal},{label:'저장',primary:true,run:async()=>{const name=$('#name-input').value.trim();if(!name)throw new Error('이름을 입력해주세요.');await callback(name);closeModal();}}]);$('#name-input').select();}
async function refreshHealth(){state.health=await api('/api/health');if(state.page==='settings')renderPage();}
async function pollJobs(){try{const jobs=await api('/api/jobs');const finished=jobs.filter(j=>!activeJob(j)&&state.jobs.some(o=>o.id===j.id&&activeJob(o)));state.jobs=jobs;for(const j of finished){if(j.state==='succeeded'){toast(`${names[j.kind]||j.kind} 작업이 완료되었습니다.`);if(j.result?.applied===false&&j.result?.cues)toast(j.result.message||'전사 결과가 기존 자막과 충돌했습니다. 완성 영상 · 작업에서 검토 후 적용하세요.',true);if(j.project_id===state.project?.id){if(j.kind==='recommend'){state.candidates=j.result?.candidates||[];state.inspector='ai';}if(j.kind==='silence'){state.ranges=j.result?.ranges||[];state.inspector='clip';}if(j.kind==='transcribe'){await flush();const fresh=await api(`/api/projects/${state.project.id}`);state.project.revision=fresh.revision;state.project.updated_at=fresh.updated_at;if(j.result?.applied!==false){state.project.cues=fresh.cues;state.project.original_cues=fresh.original_cues;state.project.transcript_engine=fresh.transcript_engine;}}if(j.kind==='preview'){const a=j.artifacts?.find(a=>a.kind==='mp4');if(a){state.previewUrl=a.url||'/api/artifacts/'+a.id;}}}}else if(j.state==='failed')toast(`${names[j.kind]||j.kind} 실패: ${typeof j.error==='object'?j.error?.message:j.error||'완성 영상 · 작업에서 확인하세요.'}`,true);}if(state.page==='exports'&&JSON.stringify(jobs)!==$('#page').dataset.jobSnapshot){renderPage();$('#page').dataset.jobSnapshot=JSON.stringify(jobs);}if(state.page==='editor'&&finished.some(j=>j.project_id===state.project?.id))renderPage();else if(state.page==='editor')updateJobStrips();}catch{}finally{pollTimer=setTimeout(pollJobs,1800);}}
function updateJobStrips(){const shown=$$('.job-strip'),actual=state.jobs.filter(j=>j.project_id===state.project?.id&&activeJob(j));if(shown.length!==actual.length){if(document.activeElement?.tagName!=='TEXTAREA'&&document.activeElement?.tagName!=='INPUT')renderPage();return;}shown.forEach((el,i)=>{const j=actual[i];const grow=$('.grow',el);if(grow)grow.textContent=j.stage||states[j.state];const pr=$('.progress',el);if(pr){pr.classList.toggle('unknown',j.progress==null);$('i',pr).style.width=Math.round((j.progress||0)*100)+'%';}const spans=$$('span',el);if(spans.length)spans.at(-1).textContent=j.progress==null?'처리 중':Math.round(j.progress*100)+'%';});}

function updateBoxes(){const c=clip();if(!c)return;$$('.element-box').forEach(el=>{const s=effectiveStyle(el.dataset.element);if(!s)return;Object.assign(el.style,{left:s.x/1080*100+'%',top:s.y/1920*100+'%',width:s.w/1080*100+'%',height:s.h/1920*100+'%'});});boundaryWarning();}
async function applyCandidates(items){await flush();state.project=await api(`/api/projects/${state.project.id}/apply-candidates`,{method:'POST',body:{candidates:items}});state.clipId=state.project.clips.at(-1)?.id;state.project.clips.forEach(c=>state.selectedClips.add(c.id));state.time=0;renderPage();toast(`${items.length}개 후보를 편집할 쇼츠로 추가했습니다.`);}
function showPlayback(url,title){modal(esc(title||'영상 확인'),`<video controls autoplay playsinline style="width:100%;max-height:65vh;background:#090c10" src="${esc(url)}"></video><p class="field-note" style="margin-top:13px">실제로 인코딩된 MP4입니다. 자막·제목·음성과 동기화를 확인하세요.</p>`,[{label:'닫기',run:closeModal}]);}
function playPreview(){const c=clip();if(!c)return;if(state.previewUrl){showPlayback(state.previewUrl,'확정 미리보기 · '+c.title);return;}confirmAction('확정 미리보기 만들기','현재 편집 데이터를 낮은 해상도의 실제 MP4로 렌더링합니다. 저장과 스타일 변경은 자동으로 반영되고 AI를 호출하지 않습니다.',async()=>{await startJob('preview');},'미리보기 렌더링');}
async function resetElement(){if(state.scope==='cue'&&selectedCue()&&['subtitle','highlight'].includes(state.element)){record();delete selectedCue()[state.element==='subtitle'?'style':'highlight_style'];changed();setInspector();updateBoxes();return;}const theme=clip()?.style?.theme||'dark';let t=state.templates.find(t=>t.style?.theme===theme)||state.templates[0];if(!t){state.templates=await api('/api/templates');t=state.templates.find(t=>t.style?.theme===theme)||state.templates[0];}if(!t?.style[state.element])throw new Error('기본 템플릿이 없습니다. 템플릿 메뉴를 확인하세요.');record();clip().style[state.element]=clone(t.style[state.element]);changed();setInspector();updateBoxes();}
function undo(redo=false){const from=redo?state.redo:state.undo,to=redo?state.undo:state.redo;if(!from.length||!state.project)return;to.push(clone({title:state.project.title,cues:state.project.cues,clips:state.project.clips}));Object.assign(state.project,from.pop());state.clipId=clip()?.id;state.time=Math.min(state.time,duration());changed();renderPage();}
const actions={
  'logo-upload':()=>$('#logo-upload').click(),'background-upload':()=>$('#background-upload').click(),'logo-remove':()=>{record();clip().style.logo.asset_id=null;changed();setInspector();},'background-remove':()=>{record();clip().style.background_asset_id=null;changed();setInspector();},
  'zoom-frame':()=>{const src=$('#preview-frame')?.src;if(!src)return;modal('현재 프레임 · 최종 출력 렌더러',`<img src="${esc(src)}" style="display:block;max-height:67vh;max-width:100%;margin:auto" alt="확대 미리보기"><p class="field-note" style="margin-top:12px">1080 × 1920 출력 기준입니다. 드래그와 위치 수정은 편집기의 미리보기에서 할 수 있습니다.</p>`,[{label:'닫기',run:closeModal}]);},
  'close-modal':closeModal,'upload':uploadDialog,'choose-video':()=>$('#video-upload').click(),
  'project-import':()=>$('#project-import').click(),'subtitle-import':()=>$('#subtitle-upload').click(),'template-import':()=>$('#template-import').click(),
  'save':async()=>{await flush();toast('프로젝트를 저장했습니다.');requestFrame();},'undo':()=>undo(),'redo':()=>undo(true),
  'new-clip':newClipDialog,'new-cue':newCueDialog,'export':exportDialog,'play':playPreview,
  'preview':async()=>{await startJob('preview');},
  'project-json':async()=>{await flush();window.location.href=`/api/projects/${state.project.id}/json`;},
  'view-grid':()=>{state.list=false;renderPage();},'view-list':()=>{state.list=true;renderPage();},
  'rename-project':()=>promptName('프로젝트 이름 변경',state.project.title,async name=>{record();state.project.title=name;changed({frame:false});await flush();renderPage();}),
  'duplicate-project':async el=>{await flush();const p=await api(`/api/projects/${el.dataset.id}/duplicate`,{method:'POST'});state.projects=await api('/api/projects');renderPage();toast(`「${p.title}」 프로젝트를 복제했습니다.`);},
  'delete-project':el=>confirmAction('프로젝트 삭제','이 프로젝트의 편집 데이터만 휴지통으로 옮깁니다. 업로드한 원본과 이미 완성한 파일은 보존합니다.',async()=>{await api(`/api/projects/${el.dataset.id}`,{method:'DELETE'});state.projects=await api('/api/projects');renderPage();toast('프로젝트를 삭제했습니다. 원본은 보존했습니다.');},'프로젝트 삭제'),
  'seek-cue':el=>{const q=state.project.cues.find(q=>q.id===el.dataset.id);if(q){state.cueId=q.id;seek(outputTime(q.start));if(state.scope==='cue'){setInspector();updateBoxes();}}},
  'cue-timing':el=>{const q=state.project.cues.find(q=>q.id===el.dataset.id);if(!q)return;modal('자막 시간 조정',`<p>표시되는 자막 시각만 수정합니다. 원본 발화의 영상·음성은 이동하거나 잘리지 않습니다.</p><div class="grid2"><label>시작 (원본 초)<input id="cue-time-start" type="number" min="0" step=".01" value="${q.start}"></label><label>종료 (원본 초)<input id="cue-time-end" type="number" min="0" step=".01" value="${q.end}"></label></div>`,[{label:'취소',run:closeModal},{label:'시간 저장',primary:true,run:async()=>{const start=Number($('#cue-time-start').value),end=Number($('#cue-time-end').value);if(start<0||end<=start||end>state.project.source.duration)throw new Error('자막 시간을 원본 범위 안에서 지정해주세요.');record();Object.assign(q,{start,end});state.project.cues.sort((a,b)=>a.start-b.start);changed();await flush();closeModal();renderPage();}}]);},
  'cue-style':el=>{state.cueId=el.dataset.id;state.scope='cue';selectElement('subtitle');seek(outputTime(selectedCue().start));},
  'highlight-cue':el=>{const q=state.project.cues.find(q=>q.id===el.dataset.id);if(!q)return;const ta=$(`textarea[data-cue-text="${q.id}"]`),selected=ta?.value.substring(ta.selectionStart,ta.selectionEnd);modal('강조할 원문 구절',`<p>실제 자막에 있는 단어·구절을 입력하세요. 해당 텍스트만 강조 스타일로 표시됩니다. 빈칸으로 저장하면 강조를 해제합니다.</p><label>강조 텍스트<input id="highlight-text" value="${esc(selected||q.highlight||'')}"></label>`,[{label:'취소',run:closeModal},{label:'강조 저장',primary:true,run:async()=>{const term=$('#highlight-text').value;if(term&&!q.text.includes(term))throw new Error('자막 원문에 있는 텍스트를 입력하세요.');record();q.highlight=term;changed();await flush();closeModal();renderPage();}}]);},
  'split-cue':el=>{const q=state.project.cues.find(q=>q.id===el.dataset.id);if(!q)return;const ta=$(`textarea[data-cue-text="${q.id}"]`),pos=ta?.selectionStart||Math.floor(q.text.length/2);if(pos<=0||pos>=q.text.length)throw new Error('자막 입력창에서 분리할 위치를 선택해주세요.');const split=q.start+(q.end-q.start)*pos/q.text.length;if(split-q.start<.05||q.end-split<.05)throw new Error('이 자막은 너무 짧아 분리할 수 없습니다.');record();const next={...clone(q),id:crypto.randomUUID(),start:split,text:q.text.slice(pos).trim()};q.text=q.text.slice(0,pos).trim();q.end=split;state.project.cues.splice(state.project.cues.findIndex(x=>x.id===q.id)+1,0,next);changed();renderPage();toast('문자 위치 비율로 시간을 나눴습니다. 자막 시각을 확인해주세요.');},
  'merge-cue':el=>{const index=state.project.cues.findIndex(q=>q.id===el.dataset.id),q=state.project.cues[index],next=state.project.cues[index+1];if(!q||!next)throw new Error('합칠 다음 자막이 없습니다.');record();q.text+='\n'+next.text;q.end=next.end;q.highlight=q.highlight||next.highlight?q.text:'';state.project.cues.splice(index+1,1);changed();renderPage();},
  'cut-cue':el=>{const q=state.project.cues.find(q=>q.id===el.dataset.id),c=clip();if(!q||!c)return;confirmAction('실제 발화 구간 삭제',`원본 ${time(q.start,true)} – ${time(q.end,true)}의 <b>영상·음성·자막</b>을 이번 쇼츠에서 제외합니다. 원본은 보존되며 실행 취소로 되돌릴 수 있습니다.`,async()=>{record();c.cuts=[...(c.cuts||[]),{start:Math.max(q.start,c.start),end:Math.min(q.end,c.end)}];state.time=Math.min(state.time,duration());changed();await flush();renderPage();},'발화 구간 제외');},
  'delete-cue':el=>{record();state.project.cues=state.project.cues.filter(q=>q.id!==el.dataset.id);changed();renderPage();toast('자막만 제거했습니다. 영상과 음성은 유지됩니다.');},
  'restore-cues':()=>confirmAction('자막 원문 복원','불러오거나 전사한 원문으로 현재 자막을 되돌립니다. 영상 삭제 구간과 디자인은 유지합니다.',async()=>{record();state.project.cues=clone(state.project.original_cues);changed();await flush();renderPage();},'원문으로 복원'),
  'source-preview':()=>{modal('원본 영상 확인',`<video id="source-player" controls autoplay playsinline style="width:100%;max-height:63vh;background:#090c10" src="/api/projects/${state.project.id}/source"></video><p class="field-note" style="margin-top:12px">원본 영상입니다. 제목·추가 자막·삭제 구간·배속이 반영되지 않습니다.</p><div class="notice">${time(state.project.source.duration,true)} · ${state.project.source.width} × ${state.project.source.height} · ${Number(state.project.source.fps||0).toFixed(2)}fps · ${state.project.source.has_audio?'음성 트랙 있음':'음성 없는 원본'}<br>원본 SHA-256: ${esc(state.project.source.hash?.slice(0,24)||'')}…</div>`,[{label:'닫기',run:closeModal}]);const v=$('#source-player');v.addEventListener('loadedmetadata',()=>v.currentTime=sourceTime(),{once:true});},
  'center-element':()=>{const effective=effectiveStyle(),s=styleTarget();if(!s)return;record();s.x=Math.round((1080-effective.w)/2);changed();setInspector();updateBoxes();},'reset-element':resetElement,
  'save-template':()=>promptName('현재 디자인을 템플릿으로 저장',clip()?.title+' 스타일',async name=>{await flush();await api('/api/templates',{method:'POST',body:{name,style:clone(clip().style)}});state.templates=await api('/api/templates');setInspector();toast('새 템플릿을 저장했습니다.');}),
  'update-template':()=>{const id=$('#template-select')?.value,t=state.templates.find(t=>t.id===id);if(!t)throw new Error('갱신할 템플릿을 선택하세요.');confirmAction('템플릿 새 버전 저장',`「${esc(t.name)}」을 현재 클립 디자인으로 갱신합니다. 기존 클립의 적용 버전과 디자인은 유지됩니다.`,async()=>{await flush();await api(`/api/templates/${t.id}`,{method:'PUT',body:{name:t.name,style:clone(clip().style)}});state.templates=await api('/api/templates');setInspector();toast('템플릿 새 버전을 저장했습니다.');},'새 버전 저장');},
  'apply-template':()=>{const id=$('#template-select')?.value;if(!id)throw new Error('적용할 템플릿을 선택해주세요.');templateApplyDialog(id);},
  'add-cut':()=>{const c=clip(),at=sourceTime();modal('삭제 구간 직접 지정',`<p>이번 클립의 영상·음성·자막에서 제외할 원본 구간입니다. 원본을 덮어쓰지 않습니다.</p><div class="grid2"><label>시작 (원본 초)<input id="cut-start" type="number" step=".01" value="${at.toFixed(2)}"></label><label>종료 (원본 초)<input id="cut-end" type="number" step=".01" value="${Math.min(c.end,at+1).toFixed(2)}"></label></div>`,[{label:'취소',run:closeModal},{label:'이 구간 제외',primary:true,run:async()=>{const start=Number($('#cut-start').value),end=Number($('#cut-end').value);if(start<c.start||end>c.end||end<=start)throw new Error('현재 쇼츠 안에서 올바른 구간을 지정해주세요.');record();c.cuts=[...(c.cuts||[]),{start,end}];state.time=Math.min(state.time,duration());changed();await flush();closeModal();renderPage();}}]);},
  'restore-cut':el=>{record();clip().cuts.splice(Number(el.dataset.index),1);changed();renderPage();},
  'silence':()=>modal('보수적인 무음 감지',`<p>먼저 삭제 후보만 찾습니다. 자동으로 자르지 않으며 결과를 검토한 뒤 적용할 수 있습니다.</p><div class="stack"><div class="grid2"><label>무음 기준 (dB)<input id="silence-threshold" type="number" min="-90" max="-10" value="-35"></label><label>최소 무음 길이 (초)<input id="silence-min" type="number" min=".1" max="10" step=".1" value=".6"></label></div><label>앞뒤에 남길 여백 (초)<input id="silence-padding" type="number" min="0" max="2" step=".05" value=".15"></label></div>`,[{label:'취소',run:closeModal},{label:'삭제 후보 찾기',primary:true,run:async()=>{const settings={threshold:Number($('#silence-threshold').value),min_duration:Number($('#silence-min').value),padding:Number($('#silence-padding').value)};await startJob('silence',{settings});closeModal();}}]),
  'apply-silence':()=>confirmAction('무음 후보 적용',`${state.ranges.length}개 무음 구간을 삭제 목록에 추가합니다. 발화의 첫음절·끝음절과 숫자 사이의 호흡이 잘리지 않았는지 확정 미리보기로 확인하세요.`,async()=>{record();clip().cuts=[...(clip().cuts||[]),...clone(state.ranges)];state.ranges=[];state.time=Math.min(state.time,duration());changed();await flush();renderPage();},'삭제 구간에 적용'),
  'duplicate-clip':()=>{record();const c=clone(clip());c.id=crypto.randomUUID();c.title+=' (복사)';state.project.clips.push(c);state.clipId=c.id;state.selectedClips.add(c.id);state.time=0;changed();renderPage();},
  'delete-clip':()=>confirmAction('선택한 클립 삭제','이 클립의 편집 데이터만 삭제합니다. 다른 클립과 원본은 보존됩니다.',async()=>{record();const id=clip().id;state.project.clips=state.project.clips.filter(c=>c.id!==id);state.selectedClips.delete(id);state.clipId=state.project.clips[0]?.id;state.time=0;changed();await flush();renderPage();},'클립 삭제'),
  'transcribe':async()=>{await refreshHealth();transcribeDialog();},
  'recommend':async()=>{const provider=$('#recommend-provider').value,min_duration=Number($('#recommend-min').value),max_duration=Number($('#recommend-max').value),count=Number($('#recommend-count').value);if(min_duration<=0||max_duration<min_duration||count<1)throw new Error('길이와 후보 수를 확인해주세요.');const settings={provider,min_duration,max_duration,count};if(provider==='remote')externalConsent('recommend',settings,s=>startJob('recommend',{settings:s}));else await startJob('recommend',{settings});},
  'apply-candidate':el=>applyCandidates([state.candidates[Number(el.dataset.index)]]),'apply-all-candidates':()=>applyCandidates(state.candidates),
  'cancel-job':async el=>{await api(`/api/jobs/${el.dataset.id}/cancel`,{method:'POST'});toast('취소를 요청했습니다. 실제 프로세스 정리 상태를 확인합니다.');},
  'retry-job':async el=>{const j=await api(`/api/jobs/${el.dataset.id}/retry`,{method:'POST'});state.jobs.push(j);renderPage();toast('작업을 다시 시작했습니다.');},
  'review-transcript':el=>{const j=state.jobs.find(j=>j.id===el.dataset.id);if(!j?.result?.cues)return;modal('보관된 전사 결과 검토',`<p>${esc(j.result.message||'현재 자막은 유지되어 있습니다. 새 전사 결과를 명시적으로 적용할 수 있습니다.')}</p><div class="notice">총 ${j.result.cues.length}개 문장 · 아래는 앞부분 미리보기입니다. 적용하면 현재 교정 자막을 대체하므로 먼저 프로젝트 JSON으로 저장하세요.</div><div class="stack" style="margin-top:15px">${j.result.cues.slice(0,10).map(q=>`<div><small>${time(q.start,true)} – ${time(q.end,true)}</small><p>${esc(q.text)}</p></div>`).join('')}</div>`,[{label:'현재 자막 유지',run:closeModal},{label:'결과 JSON 저장',run:()=>downloadJSON(j.result.cues,'전사_결과.json')},{label:'현재 자막 대체',primary:true,run:async()=>{await flush();const p=await api(`/api/projects/${j.project_id}`);const saved=await api(`/api/projects/${p.id}`,{method:'PUT',body:{title:p.title,cues:j.result.cues,clips:p.clips,revision:p.revision}});if(state.project?.id===p.id){record();state.project=saved;}closeModal();toast('검토한 전사 결과를 자막에 적용했습니다.');if(state.page==='editor')renderPage();}}]);},
  'refresh-jobs':async()=>{state.jobs=await api('/api/jobs');renderPage();},'refresh-health':async()=>{await refreshHealth();toast('로컬 환경 상태를 확인했습니다.');},
  'artifact-play':el=>showPlayback(el.dataset.url,el.dataset.name),
  'template-apply-dialog':el=>templateApplyDialog(el.dataset.id),
  'template-info':el=>{const t=state.templates.find(t=>t.id===el.dataset.id);modal(esc(t.name),`<div class="template-preview" style="border-radius:8px">${templateMini(t.style)}</div><p class="field-note" style="margin-top:16px">v${t.version} · 레이아웃 좌표와 자막 스타일을 담은 독립 템플릿입니다. 정확한 원본·문장 배치는 프로젝트의 확정 미리보기에서 확인하세요.</p>`,[{label:'닫기',run:closeModal},{label:'클립에 적용',primary:true,run:()=>templateApplyDialog(t.id)}]);},
  'template-copy':async el=>{const t=state.templates.find(t=>t.id===el.dataset.id);await api('/api/templates',{method:'POST',body:{name:t.name+' (복사)',style:clone(t.style)}});state.templates=await api('/api/templates');renderPage();toast('템플릿을 복제했습니다.');},
  'template-rename':el=>{const t=state.templates.find(t=>t.id===el.dataset.id);promptName('템플릿 이름 변경',t.name,async name=>{await api(`/api/templates/${t.id}`,{method:'PUT',body:{name,style:t.style}});state.templates=await api('/api/templates');renderPage();});},
  'template-delete':el=>confirmAction('템플릿 삭제','이 템플릿만 삭제합니다. 이미 적용한 클립의 디자인과 템플릿 버전 정보는 보존됩니다.',async()=>{await api(`/api/templates/${el.dataset.id}`,{method:'DELETE'});state.templates=await api('/api/templates');renderPage();},'템플릿 삭제'),
  'template-download':el=>{const t=state.templates.find(t=>t.id===el.dataset.id);downloadJSON(t,t.name+'.json');},
  'new-template':()=>{if(!clip()){toast('프로젝트의 디자인 편집에서 스타일을 만든 뒤 템플릿으로 저장하세요.');return;}actions['save-template']();},
  'help':()=>modal('내 첫 쇼츠 만들기',`<div class="stack"><div><h3>01 · 원본 등록과 자막 준비</h3><p>MP4 영상을 등록하고 SRT/VTT 파일을 가져오거나 수동 자막을 입력하세요. API 키 없이도 시작할 수 있습니다.</p></div><div><h3>02 · 구간과 디자인 편집</h3><p>수동 구간에서 시작·종료를 정하세요. 제목·자막·영상은 미리보기에서 드래그하거나 디자인 편집의 숫자로 조정합니다. 글자만 고치면 원본 발화는 유지됩니다.</p></div><div><h3>03 · 실제 MP4 만들기</h3><p>확정 미리보기로 결과를 검토한 뒤 MP4 내보내기를 누르세요. 여러 클립은 개별 MP4와 ZIP으로 저장됩니다. 완성 영상 메뉴에서 상태·취소·재시도와 파일을 확인합니다.</p></div><div class="notice">Ctrl+S 저장 · Ctrl+Z 실행 취소 · Ctrl+Shift+Z 다시 실행<br>미리보기 선택 후 방향키 1px 이동 · Shift + 방향키 10px 이동<br>프로젝트 JSON 저장은 원본 영상을 포함하지 않습니다.</div></div>`,[{label:'시작하기',primary:true,run:closeModal}])
};
document.addEventListener('click',async e=>{const navEl=e.target.closest('[data-nav]');if(navEl){nav(navEl.dataset.nav);return;}const op=e.target.closest('[data-open]');if(op){await openProject(op.dataset.open);return;}const cl=e.target.closest('[data-clip]');if(cl){await flush();state.clipId=cl.dataset.clip;state.time=0;state.previewUrl=null;persistView();renderPage();return;}const insp=e.target.closest('[data-inspector]');if(insp){state.inspector=insp.dataset.inspector;persistView();setInspector();return;}const elem=e.target.closest('[data-element-select]');if(elem){selectElement(elem.dataset.elementSelect);return;}const action=e.target.closest('[data-action]');if(action&&actions[action.dataset.action]){try{await actions[action.dataset.action](action);}catch(err){toast(err.message,true);}}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='scrubber'){seek(Number(el.value));return;}if(el.id==='cue-search'){state.cueSearch=el.value;$('#cue-list').innerHTML=cueCards();return;}if(el.id==='project-search'){state.projectSearch=el.value;$('#project-list').innerHTML=projectCards(state.projects.filter(p=>p.title.toLowerCase().includes(el.value.toLowerCase())));return;}if(el.dataset.cueText){const q=state.project?.cues.find(q=>q.id===el.dataset.cueText);if(q){record(true);q.text=el.value;changed();}return;}if(el.id==='clip-title'){record(true);clip().title=el.value;changed();const tab=$(`[data-clip="${clip().id}"]`);if(tab)tab.textContent=String(state.project.clips.findIndex(c=>c.id===clip().id)+1).padStart(2,'0')+' · '+el.value;}});
document.addEventListener('change',async e=>{const el=e.target;try{if(el.dataset.style){record();const key=el.dataset.style;let value=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;if(el.tagName==='SELECT'&&['true','false'].includes(value))value=value==='true';if(key==='@background')clip().style.background=value;else{styleTarget()[key]=value;}changed();updateBoxes();return;}if(el.dataset.cueHighlight){const q=state.project.cues.find(q=>q.id===el.dataset.cueHighlight);record();q.highlight=el.checked?q.text:'';changed();return;}if(el.id==='style-scope'){state.scope=el.value;setInspector();updateBoxes();return;}if(el.id==='safe-toggle'){state.safe=el.checked;const canvas=$('#canvas');$('.safe-guide',canvas)?.remove();if(state.safe)canvas.insertAdjacentHTML('beforeend','<div class="safe-guide"></div>');return;}if(el.id==='subtitles-enabled'){record();clip().subtitles_enabled=el.checked;changed();return;}if(['clip-start','clip-end','clip-speed'].includes(el.id)){const c=clip(),key={'clip-start':'start','clip-end':'end','clip-speed':'speed'}[el.id],n=Number(el.value);if(!Number.isFinite(n)||(key==='start'&&(n<0||n>=c.end))||(key==='end'&&(n<=c.start||n>state.project.source.duration))||(key==='speed'&&(n<.25||n>4))){el.value=c[key];throw new Error('원본 범위 안에서 시작·종료와 재생 속도를 확인해주세요.');}record();c[key]=n;c.cuts=(c.cuts||[]).map(x=>({start:Math.max(c.start,x.start),end:Math.min(c.end,x.end)})).filter(x=>x.end>x.start);state.time=Math.min(state.time,duration());changed();await flush();renderPage();return;}}catch(err){toast(err.message,true);}});
$('#video-upload').addEventListener('change',e=>{const file=e.target.files[0];e.target.value='';if(file)uploadVideo(file);});
$('#subtitle-upload').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file||!state.project)return;try{await flush();const f=new FormData();f.append('file',file);record();state.project=await api(`/api/projects/${state.project.id}/subtitles`,{method:'POST',body:f});state.previewUrl=null;renderPage();toast(`${state.project.cues.length}개 자막을 불러왔습니다. 시간과 내용을 확인하세요.`);}catch(err){toast(err.message,true);}});
$('#project-import').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{await flush();const f=new FormData();f.append('file',file);const p=await api('/api/projects/import',{method:'POST',body:f});await openProject(p.id);toast('프로젝트를 다시 열었습니다.');}catch(err){toast(err.message,true);}});
$('#template-import').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>2e6)throw new Error('템플릿 JSON은 2MB 이하여야 합니다.');const data=JSON.parse(await file.text());if(!data.style||!data.name)throw new Error('name과 style이 있는 템플릿 JSON을 선택하세요.');await api('/api/templates',{method:'POST',body:{name:data.name,style:data.style}});state.templates=await api('/api/templates');renderPage();toast('템플릿을 가져왔습니다.');}catch(err){toast(err.message,true);}});
for(const field of ['logo','background'])$('#'+field+'-upload').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file||!state.project)return;try{await flush();const f=new FormData();f.append('file',file);const result=await api(`/api/projects/${state.project.id}/assets`,{method:'POST',body:f});record();if(field==='logo'){clip().style.logo.asset_id=result.asset_id;clip().style.logo.enabled=true;}else clip().style.background_asset_id=result.asset_id;changed();await flush();setInspector();toast((field==='logo'?'로고':'배경')+' 이미지를 등록했습니다.');}catch(err){toast(err.message,true);}});
document.addEventListener('keydown',async e=>{const typing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();try{await flush();toast('프로젝트를 저장했습니다.');}catch(err){toast(err.message,true);}return;}if(!typing&&(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();undo(e.shiftKey);return;}if(state.page!=='editor'||typing||$('#modal').open)return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)&&document.activeElement?.id==='canvas'){e.preventDefault();const s=styleTarget(),effective=effectiveStyle();if(!s)return;record(true);s.x=effective.x;s.y=effective.y;const d=e.shiftKey?10:1;if(e.key==='ArrowLeft')s.x-=d;if(e.key==='ArrowRight')s.x+=d;if(e.key==='ArrowUp')s.y-=d;if(e.key==='ArrowDown')s.y+=d;changed();setInspector();updateBoxes();}if(e.key===' '&&document.activeElement?.tagName!=='BUTTON'){e.preventDefault();playPreview();}if(e.key==='Enter'){const open=document.activeElement?.dataset.open;if(open)await openProject(open);}});
document.addEventListener('focusin',e=>{if(e.target.dataset.cueText){state.cueId=e.target.dataset.cueText;if(state.scope==='cue'){setInspector();updateBoxes();}}});
$('#modal').addEventListener('close',()=>$$('video',$('#modal')).forEach(v=>v.pause()));
window.addEventListener('beforeunload',e=>{if(state.dirty||state.saving){e.preventDefault();e.returnValue='';}});
async function init(){const savedPage=localStorage.getItem('johnber-page');if(['projects','templates','exports','settings','editor'].includes(savedPage))state.page=savedPage;render();try{const results=await Promise.allSettled([api('/api/health'),api('/api/projects'),api('/api/templates'),api('/api/jobs')]);const keys=['health','projects','templates','jobs'];results.forEach((r,i)=>{if(r.status==='fulfilled')state[keys[i]]=r.value;else toast(r.reason.message,true);});if(state.page==='editor'){const last=localStorage.getItem('johnber-last-project');if(last&&state.projects.some(p=>p.id===last))await openProject(last);else{state.page='projects';render();}}else renderPage();}catch(e){toast(e.message,true);}pollTimer=setTimeout(pollJobs,1800);}
init();
